svg.defs:




#perfectColor1 {
  opacity:0;
  filter:url(#letterGlow104);
  animation:perfectPulse1 1.55s ease-in-out 0.16s infinite;
  pointer-events:none;
}
@keyframes perfectPulse1 {
  0%,100% { opacity:0; }
  22% { opacity:.15; }
  48% { opacity:1; }
  70% { opacity:.55; }
  84% { opacity:.18; }
}

