svg.script:
(function(){
  function react(el){
    if(!el) return;
    el.classList.remove('objectReact104');
    void el.getBoundingClientRect();
    el.classList.add('objectReact104');
    setTimeout(function(){ el.classList.remove('objectReact104'); }, 470);
  }
  document.querySelectorAll('.objectHot104').forEach(function(h){
    h.addEventListener('pointerdown', function(e){
      e.preventDefault();
      react(document.getElementById(h.getAttribute('data-target')));
    });
  });
})();
